template <class BidirectionalIt, class Allocator>
bool regex_search(BidirectionalIt first, BidirectionalIt last,
                  match_results<BidirectionalIt, Allocator>& m,
                  const basic_regex<typename iterator_traits<BidirectionalIt>::value_type>& e,
                  regex_constants::match_flag_type flags = regex_constants::match_default);

// Implementation notes: The compiler instantiates this template at compile-time based on iterator and allocator types. The 'e' parameter (basic_regex) is constructed at runtime, involving parsing the regex pattern into an internal state machine. Memory for 'm' (match_results) is managed dynamically, with submatches stored as pairs of iterators, minimizing copies but requiring careful handling of string lifetimes to avoid dangling pointers.
